import{_ as t,o,a as e,a3 as i}from"./chunks/framework.CnT1yzXN.js";const c=JSON.parse('{"title":"Сборки модов","description":"Сборки модов в Stuzhik — версионно-независимые наборы модов, которые можно применить к любому экземпляру одной кнопкой.","frontmatter":{"description":"Сборки модов в Stuzhik — версионно-независимые наборы модов, которые можно применить к любому экземпляру одной кнопкой.","head":[["meta",{"name":"keywords","content":"stuzhik сборки модов, стужик, mod collections, наборы модов minecraft, применить моды к экземпляру"}]]},"headers":[],"relativePath":"guide/collections.md","filePath":"guide/collections.md"}'),l={name:"guide/collections.md"};function r(u,a,h,n,q,d){return o(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="сборки-модов" tabindex="-1">Сборки модов <a class="header-anchor" href="#сборки-модов" aria-label="Permalink to &quot;Сборки модов&quot;">​</a></h1><p>Набор модов без привязки к конкретной версии Minecraft или загрузчику. Собираешь один раз — применяешь к любому экземпляру, а Stuzhik сам подбирает подходящие версии модов под него.</p><p>Это не модпак: сборка не содержит конфигов и настроек — только список модов, которые ты обычно ставишь вместе.</p><h2 id="зачем-это-нужно" tabindex="-1">Зачем это нужно <a class="header-anchor" href="#зачем-это-нужно" aria-label="Permalink to &quot;Зачем это нужно&quot;">​</a></h2><p>Модпак фиксирует версии. Сборка — нет. Если у тебя есть привычный набор твоих любимых модов (например, оптимизация + QoL), и ты постоянно создаёшь новые экземпляры под разные версии MC — вместо ручной переустановки одного и того же набора применяешь сборку, и подходящие версии подбираются автоматически под конкретный экземпляр.</p><h2 id="создание-сборки" tabindex="-1">Создание сборки <a class="header-anchor" href="#создание-сборки" aria-label="Permalink to &quot;Создание сборки&quot;">​</a></h2><h3 id="с-нуля" tabindex="-1">С нуля <a class="header-anchor" href="#с-нуля" aria-label="Permalink to &quot;С нуля&quot;">​</a></h3><ol><li>Раздел &quot;Сборки модов&quot; в сайдбаре → впиши название в поле &quot;Название сборки…&quot; и нажми &quot;+&quot; (&quot;Создать сборку&quot;). С пустым полем &quot;+&quot; сам спросит название</li><li>Описание (необязательно) — карандаш &quot;Изменить сборку&quot; рядом с названием</li><li>Добавляй моды через встроенный каталог — переключатель &quot;Каталог&quot; над списком модов сборки, у мода кнопка &quot;В сборку&quot;. Поиск, фильтры, всё как в обычном браузере модов</li></ol><h3 id="из-установленного-экземпляра" tabindex="-1">Из установленного экземпляра <a class="header-anchor" href="#из-установленного-экземпляра" aria-label="Permalink to &quot;Из установленного экземпляра&quot;">​</a></h3><ol><li>Раздел &quot;Сборки модов&quot; → кнопка &quot;Из экземпляра&quot; → выбери экземпляр</li><li>Выбери, какие моды включить (можно не все). В списке только моды с Modrinth и CurseForge — локальные JAR под другую версию игры не подобрать</li><li>Куда: &quot;В новую сборку&quot; (с названием) или &quot;В «…»&quot; — в открытую сейчас сборку. Затем &quot;Добавить&quot;</li></ol><h2 id="применение-сборки" tabindex="-1">Применение сборки <a class="header-anchor" href="#применение-сборки" aria-label="Permalink to &quot;Применение сборки&quot;">​</a></h2><h3 id="к-существующему-экземпляру" tabindex="-1">К существующему экземпляру <a class="header-anchor" href="#к-существующему-экземпляру" aria-label="Permalink to &quot;К существующему экземпляру&quot;">​</a></h3><ol><li>Экземпляр → вкладка &quot;Моды&quot; → кнопка &quot;Сборки модов&quot; (подсказка &quot;Применить&quot;)</li><li>Выбери сборку</li><li>Stuzhik покажет предпросмотр: что установится, что пропустится (уже есть или несовместимо), что не удалось найти под эту версию/загрузчик</li><li>Подтверди — &quot;Установить выбранные&quot;</li></ol><h3 id="при-создании-нового-экземпляра" tabindex="-1">При создании нового экземпляра <a class="header-anchor" href="#при-создании-нового-экземпляра" aria-label="Permalink to &quot;При создании нового экземпляра&quot;">​</a></h3><p>В форме создания экземпляра есть необязательное поле &quot;Сборка модов&quot; (появляется, когда у тебя есть сборки, и не для ванильного экземпляра) — моды установятся сразу после создания экземпляра, версии подберутся под его MC и загрузчик.</p><h2 id="экспорт-и-импорт" tabindex="-1">Экспорт и импорт <a class="header-anchor" href="#экспорт-и-импорт" aria-label="Permalink to &quot;Экспорт и импорт&quot;">​</a></h2><ul><li><strong>В модпак</strong> — сборку можно экспортировать в <code>.mrpack</code> (Modrinth) или <code>.stzhk</code> (формат Stuzhik), зафиксировав версии под конкретную MC-версию</li><li><strong>Импорт модпака в сборку</strong> — можно и наоборот: взять существующий модпак (Modrinth или CurseForge) и сохранить его список модов как версионно-независимую сборку</li></ul><h2 id="управление" tabindex="-1">Управление <a class="header-anchor" href="#управление" aria-label="Permalink to &quot;Управление&quot;">​</a></h2><ul><li>Дубликат сборки — если хочешь сделать вариацию не трогая оригинал</li><li>Переименование, своя иконка</li><li>Сортировка модов внутри сборки: &quot;По добавлению&quot;, &quot;По названию&quot; или &quot;По источнику&quot;</li></ul><h2 id="что-дальше" tabindex="-1">Что дальше? <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше?&quot;">​</a></h2><ul><li><a href="/guide/mods.html">Управление модами</a></li><li><a href="/guide/modpacks.html">Модпаки</a></li><li><a href="/faq.html">FAQ</a></li></ul>',21)])])}const m=t(l,[["render",r]]);export{c as __pageData,m as default};
